use std::fs;
use std::path::{Path, PathBuf};

/// The built-in wordlist of common words (fruit, animals, everyday objects...),
/// generated by tools/build_wordlist.py.
const BUILTIN_WORDS: &str = include_str!("../../words.txt");

/// Gets the directory holding config.toml and the history, creating it if needed.
/// On Windows this is a `config` folder next to the executable; elsewhere it is
/// `~/.config/passgen` (or `$XDG_CONFIG_HOME/passgen`).
pub fn get_config_directory() -> PathBuf {
    let dir = if cfg!(windows) {
        std::env::current_exe().ok().and_then(|exe| exe.parent().map(|parent| parent.join("config")))
    } else {
        dirs::config_dir().map(|config| config.join("passgen"))
    }
    .unwrap_or_else(|| PathBuf::from("config"));

    let _ = fs::create_dir_all(&dir);
    dir
}

/// Loads an icon from the embedded icon file.
pub fn load_icon() -> egui::IconData {
    let (icon_rgba, icon_width, icon_height) = {
        let icon = include_bytes!("../../icon.ico");
        let image = image::load_from_memory(icon)
            .expect("Failed to open icon path")
            .into_rgba8();
        let (width, height) = image.dimensions();
        let rgba = image.into_raw();
        (rgba, width, height)
    };

    egui::IconData {
        rgba: icon_rgba,
        width: icon_width,
        height: icon_height,
    }
}

/// Loads the wordlist: the built-in list when `path` is empty, otherwise the given file.
/// Returns the words along with a status message.
pub fn load_words(path: &Path) -> (Vec<String>, String) {
    if path.as_os_str().is_empty() {
        let words = parse_words(BUILTIN_WORDS);
        let status = format!("Using the built-in wordlist ({} words)", words.len());
        return (words, status);
    }
    if !path.exists() {
        return (Vec::new(), format!("Wordlist not found at: {:?}", path));
    }
    match fs::read_to_string(path) {
        Ok(content) => {
            let words = parse_words(&content);
            let status = format!("Successfully loaded {} words from {:?}", words.len(), path.file_name().unwrap_or_default());
            (words, status)
        }
        Err(e) => (Vec::new(), format!("Failed to read wordlist: {}", e)),
    }
}

/// Splits a wordlist into one word per line, skipping blank lines and duplicates
/// (a duplicate would make that word more likely to be picked).
fn parse_words(content: &str) -> Vec<String> {
    let mut words: Vec<String> = content
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(String::from)
        .collect();
    words.sort_unstable();
    words.dedup();
    words
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn builtin_wordlist_is_clean() {
        let (words, _) = load_words(Path::new(""));
        assert!(words.len() >= 900, "only {} words", words.len());
        for word in &words {
            let valid = (3..=8).contains(&word.len()) && word.chars().all(|c| c.is_ascii_lowercase());
            assert!(valid, "{:?} should be 3-8 lowercase letters", word);
        }
    }

    #[test]
    fn parsing_skips_blanks_and_duplicates() {
        assert_eq!(parse_words("pear\n\n apple \npear\n"), vec!["apple", "pear"]);
    }
}
